"""ClonField local image worker for the `states` render mode: scenes are generated by the Studio's own ComfyUI worker, no paid API.

This is the extension hook the engine documents (`private` with WORKERS, DEFAULTS and available()). The Studio registers a callback with
`set_generator(fn)`; `fn(prompt, shape, refs, out)` writes the image to `out` (a Path) or raises. Until a callback is set the worker
is not available, so nothing here can run by accident."""

from __future__ import annotations

_state = {"fn": None}
DEFAULTS = {"clonfield": 1}


def set_generator(fn):
    _state["fn"] = fn


def available() -> dict[str, int]:
    return {"clonfield": 1} if _state["fn"] else {}


class ClonFieldWorker:
    def __init__(self, n: int = 1):
        if not _state["fn"]:
            raise RuntimeError("o gerador local do ClonField não foi registrado")
        self.name = f"clonfield-{n}"

    def generate(self, job) -> None:
        _state["fn"](job.prompt, job.shape, list(job.refs), job.out)
        if not job.out.exists() or not job.out.stat().st_size:
            raise RuntimeError(f"o gerador local não escreveu {job.out.name}")

    def close(self) -> None:
        pass


WORKERS = {"clonfield": ClonFieldWorker}
